(** ** The lap *)

Lemma lap_0RB0LB_1LA1RC_1LB1RD_1LA0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
