  apply (fire_of_run_instr tm Cc true true l B0_0RB0LB_1LA1RC_1LB1RD_1LA0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LB_1LA1RC_1LB1RD_1LA0RC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LB_1LA1RC_1LB1RD_1LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LB_1LA1RC_1LB1RD_1LA0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LB_1LA1RC_1LB1RD_1LA0RC t p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB0LB_1LA1RC_1LB1RD_1LA0RC). split;
      [| exact (gbo_0RB0LB_1LA1RC_1LB1RD_1LA0RC j)].
    rewrite (gso_0RB0LB_1LA1RC_1LB1RD_1LA0RC p j E).
    exact (srun_sound tm true true chb_0RB0LB_1LA1RC_1LB1RD_1LA0RC B0_0RB0LB_1LA1RC_1LB1RD_1LA0RC BB1_0RB0LB_1LA1RC_1LB1RD_1LA0RC 4 8
             run_boot_0RB0LB_1LA1RC_1LB1RD_1LA0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LB_1LA1RC_1LB1RD_1LA0RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LB_1LA1RC_1LB1RD_1LA0RC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LB_1LA1RC_1LB1RD_1LA0RC : forall t, ~ In t pins_0RB0LB_1LA1RC_1LB1RD_1LA0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LB_1LA1RC_1LB1RD_1LA0RC.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LB_1LA1RC_1LB1RD_1LA0RC
      with (l := [SWin 2; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LB_1LA1RC_1LB1RD_1LA0RC
      with (l := [SWin 2; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LB_1LA1RC_1LB1RD_1LA0RC
      with (l := [SWin 1]).
