  | StD, S0 => mk S1 DL StA | StD, S1 => mk S1 DR StB end.

(** Its mirror 0LB0RC_1RC1LD_0LB1RA_1RA1LB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC1RD_0RB1LA_1LA1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S1 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC1RD_0RB1LA_1LA1RB : list Instr := [(StA, S0)].
Definition tmw_0RB0LC_1LC1RD_0RB1LA_1LA1RB : TM := tm_wrap_trs tmm_0RB0LC_1LC1RD_0RB1LA_1LA1RB pins_0RB0LC_1LC1RD_0RB1LA_1LA1RB.
Local Notation tm := tmw_0RB0LC_1LC1RD_0RB1LA_1LA1RB.

Lemma mirror_ok_0RB0LC_1LC1RD_0RB1LA_1LA1RB : mirror_tm tm_0RB0LC_1LC1RD_0RB1LA_1LA1RB = tmm_0RB0LC_1LC1RD_0RB1LA_1LA1RB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB0LC_1LC1RD_0RB1LA_1LA1RB (p : positive) : cconf := (StB, (Ip p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB0LC_1LC1RD_0RB1LA_1LA1RB.

(** ** The certificate *)

Definition A0_0RB0LC_1LC1RD_0RB1LA_1LA1RB : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_0RB0LC_1LC1RD_0RB1LA_1LA1RB : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chi_0RB0LC_1LC1RD_0RB1LA_1LA1RB : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_int_0RB0LC_1LC1RD_0RB1LA_1LA1RB : srun tm false true chi_0RB0LC_1LC1RD_0RB1LA_1LA1RB A0_0RB0LC_1LC1RD_0RB1LA_1LA1RB = Some (A1_0RB0LC_1LC1RD_0RB1LA_1LA1RB, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB0LC_1LC1RD_0RB1LA_1LA1RB : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB0LC_1LC1RD_0RB1LA_1LA1RB : sconf := mkC StB (mkS [] [S1;S0] 1 1 [S1]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StB *)
Definition Cin_0RB0LC_1LC1RD_0RB1LA_1LA1RB (v : positive) : cconf := (StB, (Ip v ++ [S1], S0, [])).
Local Notation Cin := Cin_0RB0LC_1LC1RD_0RB1LA_1LA1RB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB0LC_1LC1RD_0RB1LA_1LA1RB : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0LC_1LC1RD_0RB1LA_1LA1RB : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB0LC_1LC1RD_0RB1LA_1LA1RB : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chn_0RB0LC_1LC1RD_0RB1LA_1LA1RB : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_0RB0LC_1LC1RD_0RB1LA_1LA1RB : srun tm false true chn_0RB0LC_1LC1RD_0RB1LA_1LA1RB AI0_0RB0LC_1LC1RD_0RB1LA_1LA1RB = Some (AI1_0RB0LC_1LC1RD_0RB1LA_1LA1RB, 4, 8).
