(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0LC_1LC1RD_0RB1LA_1LA1RB : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chb_0RB0LC_1LC1RD_0RB1LA_1LA1RB : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_boot_0RB0LC_1LC1RD_0RB1LA_1LA1RB : srun tm true true chb_0RB0LC_1LC1RD_0RB1LA_1LA1RB B0_0RB0LC_1LC1RD_0RB1LA_1LA1RB = Some (BB1_0RB0LC_1LC1RD_0RB1LA_1LA1RB, 4, 8).
