(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LC_1LC1RD_0RB1LA_1LA1RB : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB0LC_1LC1RD_0RB1LA_1LA1RB : list lstep := [SWinR 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 2; SRotL 2; SFoldL 1].

Lemma run_exit_0RB0LC_1LC1RD_0RB1LA_1LA1RB : srun tm true true che_0RB0LC_1LC1RD_0RB1LA_1LA1RB BE0_0RB0LC_1LC1RD_0RB1LA_1LA1RB = Some (B1_0RB0LC_1LC1RD_0RB1LA_1LA1RB, 4, 10).
