(** 0RB0LC_1LC1RD_1LA1LA_1LC1RD *)
(** 0RB0LC_1LC1RD_1LA1LA_1LC1RD -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LC_1LC1RD_1LA1LA_1LC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DR StD end.

(** Its mirror 0LB0RC_1RC1LD_1RA1RA_1RC1LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC1RD_1LA1LA_1LC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC1RD_1LA1LA_1LC1RD : list Instr := [(StB, S0)].
Definition tmw_0RB0LC_1LC1RD_1LA1LA_1LC1RD : TM := tm_wrap_trs tmm_0RB0LC_1LC1RD_1LA1LA_1LC1RD pins_0RB0LC_1LC1RD_1LA1LA_1LC1RD.
