(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB0LC_1LC1RD_1LA1LA_1LC1RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_0RB0LC_1LC1RD_1LA1LA_1LC1RD /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_0RB0LC_1LC1RD_1LA1LA_1LC1RD = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB0LC_1LC1RD_1LA1LA_1LC1RD, cden, Z0_0RB0LC_1LC1RD_1LA1LA_1LC1RD, Z1_0RB0LC_1LC1RD_1LA1LA_1LC1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB0LC_1LC1RD_1LA1LA_1LC1RD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_0RB0LC_1LC1RD_1LA1LA_1LC1RD /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_0RB0LC_1LC1RD_1LA1LA_1LC1RD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB0LC_1LC1RD_1LA1LA_1LC1RD, cden, P0_0RB0LC_1LC1RD_1LA1LA_1LC1RD, P1_0RB0LC_1LC1RD_1LA1LA_1LC1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LC_1LC1RD_1LA1LA_1LC1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB0LC_1LC1RD_1LA1LA_1LC1RD p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB0LC_1LC1RD_1LA1LA_1LC1RD Z0_0RB0LC_1LC1RD_1LA1LA_1LC1RD Z1_0RB0LC_1LC1RD_1LA1LA_1LC1RD 0 4
               run_z_0RB0LC_1LC1RD_1LA1LA_1LC1RD (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB0LC_1LC1RD_1LA1LA_1LC1RD p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB0LC_1LC1RD_1LA1LA_1LC1RD P0_0RB0LC_1LC1RD_1LA1LA_1LC1RD P1_0RB0LC_1LC1RD_1LA1LA_1LC1RD 4 8
               run_p_0RB0LC_1LC1RD_1LA1LA_1LC1RD (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB0LC_1LC1RD_1LA1LA_1LC1RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LC_1LC1RD_1LA1LA_1LC1RD.
