  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RD_1LA1LA_1LC1RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LC_1LC1RD_1LA1LA_1LC1RD B0_0RB0LC_1LC1RD_1LA1LA_1LC1RD B1_0RB0LC_1LC1RD_1LA1LA_1LC1RD 4 7 p j' [] []).
    + exact run_ovf_0RB0LC_1LC1RD_1LA1LA_1LC1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LC_1LC1RD_1LA1LA_1LC1RD p j' E).
    + exact (geo_0RB0LC_1LC1RD_1LA1LA_1LC1RD p j' E).
    + lia.
Qed.

