Lemma wit_0RB0LC_1LC1RD_1LA1LA_1LC1RD : existsb (fun tg => cfires tmm_0RB0LC_1LC1RD_1LA1LA_1LC1RD c0 3 tg) pins_0RB0LC_1LC1RD_1LA1LA_1LC1RD = true.
