(** ** The lap *)

Lemma lap_0RB0LD_0RC1RC_1LD1RC_1RC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
