  - destruct (lapi_0RB0LD_0RC1RC_1LD1RC_1RC1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_0RC1RC_1LD1RC_1RC1LA B0_0RB0LD_0RC1RC_1LD1RC_1RC1LA B1_0RB0LD_0RC1RC_1LD1RC_1RC1LA 4 13 p j' [] []).
    + exact run_ovf_0RB0LD_0RC1RC_1LD1RC_1RC1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_0RC1RC_1LD1RC_1RC1LA p j' E).
    + exact (geo_0RB0LD_0RC1RC_1LD1RC_1RC1LA p j' E).
    + lia.
Qed.

