Lemma gz_0RB0LD_1LA1RC_1RB0LC_0RC0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_0RB0LD_1LA1RC_1RB0LC_0RC0LD /\
  lift (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_0RB0LD_1LA1RC_1RB0LC_0RC0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (Alph_00_10_1.cview_some_Alph_00_10_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB0LD_1LA1RC_1RB0LC_0RC0LD, cden, Z0_0RB0LD_1LA1RC_1RB0LC_0RC0LD, Z1_0RB0LD_1LA1RC_1RB0LC_0RC0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

