  unfold Cc_0RB0LD_1LA1RC_1RB0LC_0RC0LD, cden, P0_0RB0LD_1LA1RC_1RB0LC_0RC0LD, P1_0RB0LD_1LA1RC_1RB0LC_0RC0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
