Lemma lapi_0RB0LD_1LC1RA_1LD1RB_0RC1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
