  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LD_1LC1RA_1LD1RB_0RC1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LD_1LC1RA_1LD1RB_0RC1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LD_1LC1RA_1LD1RB_0RC1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LD_1LC1RA_1LD1RB_0RC1LC
             = (StC, (rep [S1;S1] (S j) ++ [S1], S0, [S1;S1]))).
  { unfold cden, B1_0RB0LD_1LC1RA_1LD1RB_0RC1LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S1] (S j) ++ [S1]) ++ [S0], S0, [S1;S1]))).
  { unfold Cc_0RB0LD_1LC1RA_1LD1RB_0RC1LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0LD_1LC1RA_1LD1RB_0RC1LC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_0RB0LD_1LC1RA_1LD1RB_0RC1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LD_1LC1RA_1LD1RB_0RC1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1LC1RA_1LD1RB_0RC1LC B0_0RB0LD_1LC1RA_1LD1RB_0RC1LC B1_0RB0LD_1LC1RA_1LD1RB_0RC1LC 4 14 p j' [] []).
    + exact run_ovf_0RB0LD_1LC1RA_1LD1RB_0RC1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_1LC1RA_1LD1RB_0RC1LC p j' E).
    + exact (geo_0RB0LD_1LC1RA_1LD1RB_0RC1LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB0LD_1LC1RA_1LD1RB_0RC1LC : stepn tmm_0RB0LD_1LC1RA_1LD1RB_0RC1LC 8 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_0RB0LD_1LC1RA_1LD1RB_0RC1LC 8 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_0RB0LD_1LC1RA_1LD1RB_0RC1LC 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
