Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LD_1LC1RA_1LD1RB_0RC1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LD_1LC1RA_1LD1RB_0RC1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LD_1LC1RA_1LD1RB_0RC1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LD_1LC1RA_1LD1RB_0RC1LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LD_1LC1RA_1LD1RB_0RC1LC : forall t, ~ In t pins_0RB0LD_1LC1RA_1LD1RB_0RC1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LD_1LC1RA_1LD1RB_0RC1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LD_1LC1RA_1LD1RB_0RC1LC
      with (l := [SWin 8]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LD_1LC1RA_1LD1RB_0RC1LC
      with (l := [SWin 4]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LD_1LC1RA_1LD1RB_0RC1LC
      with (l := [SWin 8; SCycL 2 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LD_1LC1RA_1LD1RB_0RC1LC
      with (l := [SWin 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LD_1LC1RA_1LD1RB_0RC1LC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LD_1LC1RA_1LD1RB_0RC1LC
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* D0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0LD_1LC1RA_1LD1RB_0RC1LC
      with (l := [SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_0RB0LD_1LC1RA_1LD1RB_0RC1LC : NonHalt tmm_0RB0LD_1LC1RA_1LD1RB_0RC1LC /\ QHBoundTr 32779478 tmm_0RB0LD_1LC1RA_1LD1RB_0RC1LC /\ QuasiHaltsTr tmm_0RB0LD_1LC1RA_1LD1RB_0RC1LC.
Proof.
  apply (lap_qh_stage tmm_0RB0LD_1LC1RA_1LD1RB_0RC1LC pins_0RB0LD_1LC1RA_1LD1RB_0RC1LC Cc 1 8 32779478).
  - exact bootq_0RB0LD_1LC1RA_1LD1RB_0RC1LC.
  - intros p _. apply lap_0RB0LD_1LC1RA_1LD1RB_0RC1LC.
  - intros t Ht p _. apply fire_0RB0LD_1LC1RA_1LD1RB_0RC1LC. exact Ht.
  - exact wit_0RB0LD_1LC1RA_1LD1RB_0RC1LC.
  - vm_cast_no_check (eq_refl true).
Qed.

Theorem qhtr_0RB0LD_1LC1RA_1LD1RB_0RC1LC : NonHalt tm_0RB0LD_1LC1RA_1LD1RB_0RC1LC /\ QHBoundTr 32779478 tm_0RB0LD_1LC1RA_1LD1RB_0RC1LC /\ QuasiHaltsTr tm_0RB0LD_1LC1RA_1LD1RB_0RC1LC.
