    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB0LD_1LC1RB_1RD1LA_1RD1LA P0_0RB0LD_1LC1RB_1RD1LA_1RD1LA P1_0RB0LD_1LC1RB_1RD1LA_1RD1LA 4 8
