  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LD_1LC1RB_1RD1LA_1RD1LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LD_1LC1RB_1RD1LA_1RD1LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
